sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Atezolizumab' AND "Trial phase" = 'Phase 3' AND "Type of combination" = 'ICI+MEKi';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Atezolizumab' AND "Trial phase" = 'Phase 3' AND "Type of combination" = 'ICI+MEKi'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_meki_agents(source_value) AS "meki_agents"
FROM base;
